function calculateDrawdownRecovery(drawdownPct){const d=Math.max(0,Math.min(99.99,num(drawdownPct)));return{drawdownPct:d,recoveryPct:d/(100-d)*100,sourcePages:'155-156, 175-176',note:'손실 후 원금 복구에 필요한 수익률 계산.'}}
function calculateCompounding({principal,periodReturnPct,periods,reinvestPct=100}={}){const p=num(principal),r=num(periodReturnPct)/100*Math.max(0,Math.min(100,num(reinvestPct,100)))/100,n=Math.max(0,Math.floor(num(periods)));if(!(p>=0&&n>=0))return{available:false};const final=p*((1+r)**n);return{available:true,principal:p,periodReturnPct:num(periodReturnPct),reinvestPct:num(reinvestPct,100),periods:n,final,profit:final-p,sourcePages:'177-178'}}
