function pearsonCorrelation(a,b){const n=Math.min(a?.length||0,b?.length||0);if(n<3)return null;const x=a.slice(-n).map(num),y=b.slice(-n).map(num),mx=avg(x),my=avg(y);let top=0,sx=0,sy=0;for(let i=0;i<n;i++){const dx=x[i]-mx,dy=y[i]-my;top+=dx*dy;sx+=dx*dx;sy+=dy*dy}const den=Math.sqrt(sx*sy);return den?top/den:null}
function correlationReturns(prices){const a=(prices||[]).map(num),o=[];for(let i=1;i<a.length;i++){if(a[i-1]!==0)o.push((a[i]-a[i-1])/Math.abs(a[i-1]))}return o}
function analyzeCorrelation({seriesA=[],seriesB=[],timeframes=null}={}){const ra=correlationReturns(seriesA),rb=correlationReturns(seriesB),coef=pearsonCorrelation(ra,rb);let relation='데이터 부족';if(finite(coef))relation=coef>=.7?'강한 양의 상관':coef<=-.7?'강한 음의 상관':Math.abs(coef)<.3?'낮은 상관':'중간 상관';const tf={};if(timeframes&&typeof timeframes==='object')for(const [k,v] of Object.entries(timeframes)){const a=v?.a||v?.seriesA||[],b=v?.b||v?.seriesB||[];tf[k]=pearsonCorrelation(correlationReturns(a),correlationReturns(b))}return{coefficient:coef,relation,timeframes:tf,sourcePages:'352-370',notes:['상관계수는 -1~+1 범위','상관은 시간에 따라 변할 수 있음','시장심리·경제뉴스로 상관이 약화/변화할 수 있음','책은 상관을 단독 신호가 아닌 위험관리·헤지·분산·확인 도구로 사용']}}
function correlationRiskGuidance(coef){const c=num(coef,0),abs=Math.abs(c);return{coefficient:c,exposure:abs>=.8?'중복 노출 매우 높음':abs>=.6?'중복 노출 높음':abs>=.3?'중복 노출 보통':'중복 노출 낮음',ideas:c>=.6?['같은 방향 포지션을 여러 종목에 겹치면 실질 위험이 커질 수 있음','헤지 목적이면 반대 방향 노출을 검토']:c<=-.6?['반대 방향으로 움직이는 경향을 분산/헤지 관점에서 활용 가능','상관 붕괴 여부를 계속 확인']:['상관만으로 포지션 관계를 단정하지 않기','다른 기술·펀더멘털 근거와 함께 확인'],sourcePages:'358-366'}}
function detectPinBars(input){const c=rows(input),out=[];for(let i=Math.max(0,c.length-12);i<c.length;i++){const x=c[i],p=part(x),rng=p.r;if(rng<=0||p.bp>.38)continue;const bull=p.l>=Math.max(p.b*2,rng*.52)&&p.u<=rng*.25,bear=p.u>=Math.max(p.b*2,rng*.52)&&p.l<=rng*.25;if(bull||bear)out.push({id:bull?'bullish-pin-bar':'bearish-pin-bar',label:bull?'상승 핀바':'하락 핀바',kind:'치트시트',side:bull?'상승':'하락',index:i,time:x.time,sourcePage:379,score:76,status:'READY',reasons:[bull?'긴 아래꼬리로 저가 거부':'긴 위꼬리로 고가 거부','작은 몸통','책은 지지/저항·다른 신호 확인과 함께 사용'],invalidation:bull?x.low:x.high})}return out}
function detectMWVariants(input){const base=detectChartPatterns(input).filter(x=>x.id==='double-top'||x.id==='double-bottom');return base.map(p=>{const pts=p.points||[],span=pts.length?pts.at(-1).i-pts[0].i:0;let variant='simple';if(span>=28)variant='extended';else if(span<=10)variant='short';return{...p,id:(p.id==='double-top'?'m-':'w-')+variant,label:(p.id==='double-top'?'M ':'W ')+(variant==='extended'?'확장형':variant==='short'?'단축형':'기본형'),sourcePage:385,score:Math.max(p.score||0,78),reasons:[...(p.reasons||[]),'책의 M/W 기본·확장·단축 형태를 기간 길이로 분류']}})}
function detectBookChoch(input){const c=rows(input),pv=swingPivots(c);if(c.length<20||pv.highs.length<2||pv.lows.length<2)return{detected:false,sourcePages:'399-400'};const lastClose=last(c).close,h0=pv.highs.at(-2),h1=pv.highs.at(-1),l0=pv.lows.at(-2),l1=pv.lows.at(-1);let side=null,level=null;if(l1.price<l0.price&&lastClose>h1.price){side='상승';level=h1.price}else if(h1.price>h0.price&&lastClose<l1.price){side='하락';level=l1.price}return{detected:!!side,side,level,sourcePages:'399-400',reasons:side?['기존 구조의 반대편 스윙 레벨 종가 돌파','책의 Change of Character 개념 자동화 근사','추세선/고저점/지지저항으로 추가 확인']:[]}}
function buildZones(input){const c=rows(input),ind=computeIndicators(c),psych=psychologicalLevels(ind.last),pv=ind.pivot||{},fib=ind.fibonacci?.levels||{},sr=ind.supportResistance||{};const zones=[];const add=(id,label,price,type,page)=>{if(finite(price))zones.push({id,label,price:num(price),type,sourcePage:page})};add('classic-support','클래식 지지',sr.support,'support',389);add('classic-resistance','클래식 저항',sr.resistance,'resistance',389);add('pivot','Pivot',pv.pivot,'pivot',390);add('pivot-s1','Pivot S1',pv.s1,'support',390);add('pivot-r1','Pivot R1',pv.r1,'resistance',390);add('fib-382','Fib 38.2',fib['38.2'],'fib',392);add('fib-500','Fib 50',fib['50'],'fib',392);add('fib-618','Fib 61.8',fib['61.8'],'fib',392);for(const [i,v] of (psych.levels||[]).entries())add('psych-'+i,'심리적 레벨',v,'psychological',374);const w=c.slice(-50);if(w.length>=20){const vols=w.map(x=>x.volume).filter(finite),vavg=avg(vols);const impulse=w.filter(x=>x.volume>=vavg*1.5);if(impulse.length){const low=Math.min(...impulse.map(x=>x.low)),high=Math.max(...impulse.map(x=>x.high));add('demand-zone','수요 후보',low,'demand',375);add('supply-zone','공급 후보',high,'supply',375)}}return{zones,sourcePages:'373-376,389-393',note:'책의 classic S/R·supply/demand·pivot·Fibonacci·psychological levels를 차트 데이터로 근사'}}
function detectReversalChecklist(input){const c=rows(input),ind=computeIndicators(c),chart=detectChartPatterns(c),pins=detectPinBars(c),fake=detectFakeout(c),choch=detectBookChoch(c),lastp=last(c)?.close,ema20=ind.movingAverage?.ema20;const evidence=[];if(chart.some(x=>['double-top','double-bottom','head-shoulders','inverse-head-shoulders','triple-top','triple-bottom'].includes(x.id)))evidence.push('반전형 차트 패턴');if(pins.length)evidence.push('핀바/긴 꼬리 거부');if(fake.detected)evidence.push('가짜 돌파 후 범위 복귀');if(choch.detected)evidence.push('CHoCH 후보');if(finite(ind.rsi)&&(ind.rsi>=70||ind.rsi<=30))evidence.push('RSI 극단 영역');if(finite(lastp)&&finite(ema20)&&Math.abs(lastp-ema20)/Math.max(Math.abs(lastp),1e-9)<.01)evidence.push('이평선 근접/반응 구간');return{evidence,score:Math.min(100,35+evidence.length*12),sourcePages:'383-400',note:'책의 trendline break·reversal chart pattern·momentum divergence·candlestick·volume·S/R·structure change 요소를 체크리스트로 통합'}}
