function detectMomentumDivergence(input){const c=rows(input);if(c.length<30)return{available:false};const closes=c.map(x=>x.close),R=rsi(closes),M=macd(closes),pv=swingPivots(c,2,2),last2=a=>a.filter(x=>x.i<c.length-1).slice(-2),lows=last2(pv.lows),highs=last2(pv.highs),out=[];if(lows.length===2){const[a,b]=lows,priceLower=b.price<a.price,rsiHigher=finite(R[a.i])&&finite(R[b.i])&&R[b.i]>R[a.i],macdHigher=finite(M.hist[a.i])&&finite(M.hist[b.i])&&M.hist[b.i]>M.hist[a.i];if(priceLower&&(rsiHigher||macdHigher))out.push({side:'상승',type:'bullish-divergence',label:'상승 다이버전스',priceA:a.price,priceB:b.price,rsiA:R[a.i],rsiB:R[b.i],macdA:M.hist[a.i],macdB:M.hist[b.i],score:(rsiHigher?1:0)+(macdHigher?1:0),sourcePages:'336-351'})}if(highs.length===2){const[a,b]=highs,priceHigher=b.price>a.price,rsiLower=finite(R[a.i])&&finite(R[b.i])&&R[b.i]<R[a.i],macdLower=finite(M.hist[a.i])&&finite(M.hist[b.i])&&M.hist[b.i]<M.hist[a.i];if(priceHigher&&(rsiLower||macdLower))out.push({side:'하락',type:'bearish-divergence',label:'하락 다이버전스',priceA:a.price,priceB:b.price,rsiA:R[a.i],rsiB:R[b.i],macdA:M.hist[a.i],macdB:M.hist[b.i],score:(rsiLower?1:0)+(macdLower?1:0),sourcePages:'336-351'})}return{available:true,signals:out,best:out.sort((a,b)=>b.score-a.score)[0]||null,note:'가격 스윙과 RSI/MACD 히스토그램의 비확정형 자동 비교. 단독 진입 신호가 아님.'}}

function assessVolumeBehavior(input){const c=rows(input);if(c.length<25)return{available:false};const vols=c.map(x=>num(x.volume)),lastV=last(vols),base20=avg(vols.slice(-21,-1)),recent5=avg(vols.slice(-5)),prior10=avg(vols.slice(-20,-10)),pre10=avg(vols.slice(-10)),rvol=base20?lastV/base20:null,contraction=prior10&&pre10?pre10/prior10:null,price=last(c).close,range20=Math.max(...c.slice(-20).map(x=>x.high))-Math.min(...c.slice(-20).map(x=>x.low)),atrNow=last(atr(c))||0,compressed=atrNow&&range20?range20/20<=atrNow*1.35:false;let state='NORMAL';if(finite(rvol)&&rvol>=2)state='EXPANSION';else if(finite(contraction)&&contraction<=.72)state='CONTRACTION';return{available:true,rvol,contraction,compressed,state,lastVolume:lastV,base20,recent5,price,sourcePages:'77-124,205-246',notes:[state==='EXPANSION'?'현재 거래량이 최근 기준 대비 확장':'현재 거래량 폭발은 미확인',finite(contraction)&&contraction<=.72?'최근 거래량 수축 확인':'강한 거래량 수축은 미확인',compressed?'가격 범위 압축 후보':'가격 압축 기준 미충족']}}

